import { readdirSync, readFileSync, writeFileSync } from "node:fs";

/**
 * Bundles src/storage/migrations/NNNN_name.sql into src/storage/migrations.generated.ts so the
 * browser build needs no SQL file loader. Run `pnpm build:migrations` after editing a .sql file;
 * a test fails when the generated file is out of date.
 */

const dir = new URL("../src/storage/migrations/", import.meta.url);
const target = new URL("../src/storage/migrations.generated.ts", import.meta.url);

export function renderMigrations(): string {
  const files = readdirSync(dir)
    .filter((name) => /^\d{4}_[a-z0-9_]+\.sql$/.test(name))
    .sort();
  const entries = files.map((name) => {
    const version = Number(name.slice(0, 4));
    const sql = readFileSync(new URL(name, dir), "utf8");
    return `  { version: ${version}, name: ${JSON.stringify(name.slice(5, -4))}, sql: ${JSON.stringify(sql)} },`;
  });
  return [
    "// Generated by scripts/build-migrations.ts from src/storage/migrations/*.sql. Do not edit.",
    "",
    "export interface Migration {",
    "  readonly version: number;",
    "  readonly name: string;",
    "  readonly sql: string;",
    "}",
    "",
    "export const MIGRATIONS: readonly Migration[] = [",
    ...entries,
    "];",
    "",
  ].join("\n");
}

if (import.meta.main) {
  writeFileSync(target, renderMigrations());
}
